def get_component_coords(grid, color):
    """Returns list of lists, where each inner list is one connected component"""
    visited = set()
    comps = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r,c) not in visited:
                comp = []
                stack = [(r,c)]
                visited.add((r,c))
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                stack.append((nr,nc))
                comps.append(sorted(comp))
    return comps

