def get_cell_stats(grid):
    cells = []
    visited = set()

    def dfs(r, c, color, comp_cells):
        queue = [(r, c)]
        visited.add((r,c))
        while queue:
            cr, cc = queue.pop(0)
            comp_cells.append((cr, cc))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == color and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    queue.append((nr,nc))

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r,c) not in visited:
                comp_cells = []
                dfs(r, c, grid[r][c], comp_cells)
                avg_c = sum(col for _, col in comp_cells)/len(comp_cells)
                cells.append({'color': grid[r][c], 'avg_c': avg_c, 'cells': comp_cells})

    return cells

