                cells_by_color[color].append((color, r, c))
    return cells_by_color

inp_test = test_inp
cells_by_color = get_cells_by_color(inp_test)

output_grid = [[0]*10 for _ in range(10)]

for color, cells in cells_by_color.items():
    cells_sorted = sorted(cells, key=lambda x: (x[2], x[1]))  # Sort by col then row

    left_zone = [(c, r, orig_c) for c,(r,orig_c) in enumerate(cells_sorted) if orig_c < 5]
    right_zone = [(c, r, orig_c) for c,(r,orig_c) in enumerate(cells_sorted) if orig_c >= 5]

    # Left zone → bottom band
    for idx, (_, orig_r, orig_c) in enumerate(left_zone):
        new_r = 8 + idx // 4
        new_c = idx % 4 * 2
        if 0 <= new_r < 10 and 0 <= new_c < 10:
            output_grid[new_r][new_c] = color

    # Right zone → top band  
    for idx, (_, orig_r, orig_c) in enumerate(right_zone):
        new_r = 5 + idx // 4
        new_c = 4 + idx % 4 * 2
        if 0 <= new_r < 10 and 0 <= new_c < 10:
            output_grid[new_r][new_c] = color

print("Output:")
for row in output_grid:
    print(row)

total_in = sum(sum(row) for row in inp_test)
total_out = sum(sum(row) for row in output_grid)
print(f"\nTotal: IN={total_in}, OUT={total_out}")

for c in [2, 3]:
    count_in = sum(row.count(c) for row in inp_test)
    count_out = sum(row.count(c) for row in output_grid)
    status = "✓" if count_in == count_out else f"✗ IN={count_in} OUT={count_out}"
    print(f"Color {c}: {status}")
